# (tópico, norma, [artigos], gabarito, enunciado, comentário, tipo_erro)
T="P1-M4-7.1"
Q=[
(T,"RICD",[1],"E","Havendo motivo relevante ou de força maior, a Câmara poderá reunir-se em outro edifício por decisão do Presidente, independentemente de referendo.","Art. 1º, p.ú.: deliberação da Mesa, ad referendum da maioria absoluta dos Deputados.","competencia"),
(T,"RICD",[1],"C","A Câmara dos Deputados, com sede na Capital Federal, funciona no Palácio do Congresso Nacional, podendo, por motivo relevante ou de força maior, reunir-se em outro ponto do território nacional.","Art. 1º, caput e parágrafo único.","leitura"),
(T,"RICD",[2],"C","As sessões legislativas ordinárias da Câmara realizam-se de 2 de fevereiro a 17 de julho e de 1º de agosto a 22 de dezembro.","Art. 2º, I.","prazo"),
(T,"RICD",[2],"E","A sessão legislativa ordinária será interrompida em 17 de julho mesmo que ainda não tenha sido aprovada a lei de diretrizes orçamentárias.","Art. 2º, § 3º: não será interrompida enquanto não aprovada a LDO.","leitura"),
(T,"RICD",[2],"C","Se o Congresso Nacional for convocado extraordinariamente, a Câmara dos Deputados somente deliberará sobre a matéria objeto da convocação.","Art. 2º, § 4º.","leitura"),
(T,"RICD",[2],"E","As sessões preparatórias precedem todas as sessões legislativas ordinárias de cada legislatura.","Art. 2º, § 2º: apenas a primeira e a terceira sessões legislativas ordinárias da legislatura.","tipo"),
(T,"RICD",[3],"E","O candidato diplomado Deputado Federal deve apresentar o diploma à Mesa até 15 de fevereiro do ano de instalação da legislatura.","Art. 3º: até 31 de janeiro.","prazo"),
(T,"RICD",[3],"C","O nome parlamentar compor-se-á, em regra, de apenas dois elementos: um prenome e o nome, dois nomes ou dois prenomes.","Art. 3º, § 1º (salvo, a juízo do Presidente, para evitar confusões).","leitura"),
(T,"RICD",[4],"C","No dia 1º de fevereiro do primeiro ano de cada legislatura, os candidatos diplomados reúnem-se em sessão preparatória, na sede da Câmara dos Deputados.","Art. 4º, caput.","prazo"),
(T,"RICD",[4],"E","Na sessão preparatória de instalação da legislatura, assume a direção dos trabalhos o Deputado mais jovem entre os diplomados.","Art. 4º, § 1º: o último Presidente, se reeleito Deputado; na falta, o Deputado mais idoso dentre os de maior número de legislaturas.","competencia"),
(T,"RICD",[4],"C","O compromisso de posse não admite modificação de conteúdo ou ritual, nem declaração oral ou escrita no ato, nem posse por procurador.","Art. 4º, § 4º.","podedeve"),
(T,"RICD",[4],"E","A posse do Deputado deve ocorrer em quinze dias, prorrogáveis por igual período, salvo força maior ou enfermidade comprovadas.","Art. 4º, § 6º: trinta dias, prorrogáveis por igual período, a requerimento.","prazo"),
(T,"RICD",[4],"C","Não se considera investido no mandato de Deputado Federal quem deixar de prestar o compromisso nos estritos termos regimentais.","Art. 4º, § 8º.","leitura"),
(T,"RICD",[4],"E","O Suplente de Deputado deve prestar novo compromisso a cada convocação.","Art. 4º, § 7º: tendo prestado uma vez, fica dispensado nas convocações subsequentes.","podedeve"),
(T,"RICD",[5],"C","A eleição da Mesa na primeira sessão legislativa ocorre na segunda sessão preparatória, em 1º de fevereiro, para mandato de dois anos.","Art. 5º, caput.","prazo"),
(T,"RICD",[5],"E","Enquanto não for escolhido o Presidente, apuram-se normalmente os votos para os demais cargos da Mesa.","Art. 5º, § 2º: não se procede à apuração para os demais cargos.","leitura"),
(T,"RICD",[5],"C","Não se considera recondução a eleição para o mesmo cargo da Mesa em legislaturas diferentes, ainda que sucessivas.","Art. 5º, § 1º.","leitura"),
(T,"RICD",[6],"C","No terceiro ano de cada legislatura, a eleição da Mesa realiza-se antes de inaugurada a sessão legislativa, sob a direção da Mesa da sessão anterior.","Art. 6º, caput.","leitura"),
(T,"RICD",[7],"C","A eleição dos membros da Mesa faz-se por escrutínio secreto e pelo sistema eletrônico, exigindo-se maioria absoluta no primeiro escrutínio e maioria simples no segundo.","Art. 7º, caput, com presença da maioria absoluta dos Deputados.","quorum"),
(T,"RICD",[7],"E","Se nenhum candidato alcançar maioria absoluta no primeiro escrutínio, realiza-se segundo escrutínio com os 3 (três) mais votados para cada cargo.","Art. 7º, III: os 2 (dois) mais votados.","quorum"),
(T,"RICD",[7],"C","Em caso de empate na eleição da Mesa, é eleito o candidato mais idoso dentre os de maior número de legislaturas.","Art. 7º, IV.","leitura"),
(T,"RICD",[7],"E","No caso de avaria do sistema eletrônico, a eleição por cédulas utiliza 2 (duas) urnas, uma para o Presidente e outra para os demais membros.","Art. 7º, p.ú., III: 4 (quatro) urnas, 2 para o Presidente e 2 para os demais.","tipo"),
(T,"RICD",[8],"C","Na composição da Mesa será assegurada, tanto quanto possível, a representação proporcional dos Partidos ou Blocos Parlamentares.","Art. 8º, caput.","leitura"),
(T,"RICD",[8],"E","Ocorrida vaga na Mesa até 30 de novembro do segundo ano de mandato, será preenchida mediante eleição dentro de dez sessões.","Art. 8º, § 2º: dentro de cinco sessões.","prazo"),
(T,"RICD",[8],"C","É assegurada a participação de um membro da Minoria na Mesa, ainda que pela proporcionalidade não lhe caiba lugar.","Art. 8º, § 3º.","leitura"),
(T,"RICD",[8],"E","O membro da Mesa que mudar de legenda partidária mantém o cargo até o fim do mandato.","Art. 8º, § 5º: perde automaticamente o cargo.","podedeve"),
(T,"RICD",[9],"C","Cada Líder poderá indicar Vice-Líderes na proporção de um por quatro Deputados, ou fração, que constituam sua representação.","Art. 9º, § 1º.","quorum"),
(T,"RICD",[9],"E","Líderes e Vice-Líderes podem integrar a Mesa, desde que licenciados da Liderança.","Art. 9º, § 5º: não poderão integrar a Mesa.","podedeve"),
(T,"RICD",[10],"E","O Líder pode participar dos trabalhos de qualquer Comissão de que não seja membro, com direito a voto.","Art. 10, III: sem direito a voto, podendo encaminhar a votação ou requerer verificação.","competencia"),
(T,"RICD",[10],"C","O Líder pode encaminhar a votação de proposição sujeita à deliberação do Plenário por tempo não superior a um minuto.","Art. 10, IV.","prazo"),
(T,"RICD",[11],"C","A Liderança do Governo é composta por Líder e 20 (vinte) Vice-Líderes, indicados pelo Presidente da República.","Art. 11, caput.","quorum"),
(T,"RICD",[11],"E","A Liderança da Minoria é composta de Líder e vinte Vice-Líderes.","Art. 11-A: Líder e nove Vice-Líderes.","quorum"),
(T,"RICD",[12],"E","É admitida a formação de Bloco Parlamentar que reúna ao menos um centésimo dos membros da Câmara.","Art. 12, § 3º: não será admitido Bloco com menos de três centésimos dos membros.","quorum"),
(T,"RICD",[12],"C","O Bloco Parlamentar tem existência circunscrita à legislatura, e a agremiação integrante de um Bloco não pode fazer parte de outro concomitantemente.","Art. 12, §§ 5º e 9º.","leitura"),
(T,"RICD",[13],"C","Se nenhuma representação atingir a maioria absoluta, assume as funções da Maioria o Partido ou Bloco que tiver o maior número de representantes.","Art. 13, p.ú.","leitura"),
(T,"RICD",[14],"E","A Mesa compõe-se de Presidente, dois Vice-Presidentes e seis Secretários.","Art. 14, § 1º: quatro Secretários.","quorum"),
(T,"RICD",[14],"C","A Mesa reúne-se ordinariamente uma vez por quinzena e, extraordinariamente, quando convocada pelo Presidente ou por quatro de seus membros efetivos.","Art. 14, § 3º.","prazo"),
(T,"RICD",[14],"E","Perde o lugar o membro da Mesa que faltar a três reuniões ordinárias consecutivas sem causa justificada.","Art. 14, § 4º: cinco reuniões ordinárias consecutivas.","prazo"),
(T,"RICD",[14],"C","Os membros efetivos da Mesa não podem fazer parte de Liderança nem de Comissão Permanente, Especial ou de Inquérito.","Art. 14, § 5º.","podedeve"),
(T,"RICD",[15],"C","Compete à Mesa aplicar a penalidade de censura escrita a Deputado.","Art. 15, XV.","competencia"),
(T,"RICD",[15],"E","Compete à Mesa propor ação de inconstitucionalidade somente a requerimento de Comissão.","Art. 15, IV: por iniciativa própria ou a requerimento de Deputado ou Comissão.","iniciativa"),
(T,"RICD",[15],"C","A Mesa dispõe do prazo decadencial de 5 (cinco) dias úteis, contado do conhecimento do fato, para propor a suspensão cautelar do exercício do mandato.","Art. 15, § 2º.","prazo"),
(T,"RICD",[15],"E","A proposta de suspensão cautelar do mandato é decidida pelo Conselho de Ética em votação secreta, no prazo de 10 dias úteis.","Art. 15, § 3º: votação ostensiva, 3 (três) dias úteis.","prazo"),
(T,"RICD",[15],"C","O recurso contra a decisão do Conselho de Ética sobre suspensão cautelar é apreciado pelo Plenário na sessão imediatamente subsequente, exigida maioria absoluta para aprovar ou manter a suspensão.","Art. 15, § 4º.","quorum"),
(T,"RICD",[16],"E","O cargo de Presidente da Câmara é privativo de brasileiro nato ou naturalizado há mais de dez anos.","Art. 16, p.ú.: privativo de brasileiro nato.","tipo"),
]
